    msg.extra = widget::WIDGET_ACTIVE;
    BroadcastMessage(&msg);

    msg.codeX = widget::WIDGET_SET_ICON_FRAME;
    msg.extra = gpGame->GetTown(townId)->GetPortraitFrame(true);
